test "aarch64 NEON vs LLVM" {
    if (!opts.aarch64) return error.SkipZigTest;
    const n = @import("aarch64/neon.zig");
    var cb = CodeBuffer.init(std.testing.allocator);
    defer cb.deinit();
    var fails: u32 = 0;
    cb.reset();
    try n.add(&cb, .s4, 0, 1, 2);
    fails += check(&.{ 0x20, 0x84, 0xa2, 0x4e }, cb.code(), "add v0.4s, v1.4s, v2.4s");
    cb.reset();
    try n.add(&cb, .b16, 31, 7, 9);
    fails += check(&.{ 0xff, 0x84, 0x29, 0x4e }, cb.code(), "add v31.16b, v7.16b, v9.16b");
    cb.reset();
    try n.add(&cb, .d2, 3, 4, 5);
    fails += check(&.{ 0x83, 0x84, 0xe5, 0x4e }, cb.code(), "add v3.2d, v4.2d, v5.2d");
    cb.reset();
    try n.add(&cb, .h8, 3, 4, 5);
    fails += check(&.{ 0x83, 0x84, 0x65, 0x4e }, cb.code(), "add v3.8h, v4.8h, v5.8h");
    cb.reset();
    try n.sub(&cb, .s4, 8, 9, 10);
    fails += check(&.{ 0x28, 0x85, 0xaa, 0x6e }, cb.code(), "sub v8.4s, v9.4s, v10.4s");
    cb.reset();
    try n.mul(&cb, .s4, 1, 2, 3);
    fails += check(&.{ 0x41, 0x9c, 0xa3, 0x4e }, cb.code(), "mul v1.4s, v2.4s, v3.4s");
    cb.reset();
    try n.mul(&cb, .h8, 1, 2, 3);
    fails += check(&.{ 0x41, 0x9c, 0x63, 0x4e }, cb.code(), "mul v1.8h, v2.8h, v3.8h");
    cb.reset();
    try n.fadd(&cb, .s4, 0, 1, 2);
    fails += check(&.{ 0x20, 0xd4, 0x22, 0x4e }, cb.code(), "fadd v0.4s, v1.4s, v2.4s");
    cb.reset();
    try n.fadd(&cb, .d2, 20, 21, 22);
    fails += check(&.{ 0xb4, 0xd6, 0x76, 0x4e }, cb.code(), "fadd v20.2d, v21.2d, v22.2d");
    cb.reset();
    try n.fsub(&cb, .s4, 0, 1, 2);
    fails += check(&.{ 0x20, 0xd4, 0xa2, 0x4e }, cb.code(), "fsub v0.4s, v1.4s, v2.4s");
    cb.reset();
    try n.fmul(&cb, .s4, 5, 6, 7);
    fails += check(&.{ 0xc5, 0xdc, 0x27, 0x6e }, cb.code(), "fmul v5.4s, v6.4s, v7.4s");
    cb.reset();
    try n.fmul(&cb, .d2, 5, 6, 7);
    fails += check(&.{ 0xc5, 0xdc, 0x67, 0x6e }, cb.code(), "fmul v5.2d, v6.2d, v7.2d");
    cb.reset();
    try n.fmla(&cb, .s4, 0, 1, 2);
    fails += check(&.{ 0x20, 0xcc, 0x22, 0x4e }, cb.code(), "fmla v0.4s, v1.4s, v2.4s");
    cb.reset();
    try n.andv(&cb, 0, 1, 2);
    fails += check(&.{ 0x20, 0x1c, 0x22, 0x4e }, cb.code(), "and v0.16b, v1.16b, v2.16b");
    cb.reset();
    try n.orr(&cb, 3, 4, 5);
    fails += check(&.{ 0x83, 0x1c, 0xa5, 0x4e }, cb.code(), "orr v3.16b, v4.16b, v5.16b");
    cb.reset();
    try n.eor(&cb, 30, 29, 28);
    fails += check(&.{ 0xbe, 0x1f, 0x3c, 0x6e }, cb.code(), "eor v30.16b, v29.16b, v28.16b");
    cb.reset();
    try n.ldrQ(&cb, 0, .x1, 0);
    fails += check(&.{ 0x20, 0x0, 0xc0, 0x3d }, cb.code(), "ldr q0, [x1]");
    cb.reset();
    try n.ldrQ(&cb, 17, .zr_sp, 4080);
    fails += check(&.{ 0xf1, 0xff, 0xc3, 0x3d }, cb.code(), "ldr q17, [sp, #4080]");
    cb.reset();
    try n.strQ(&cb, 2, .x3, 32);
    fails += check(&.{ 0x62, 0x8, 0x80, 0x3d }, cb.code(), "str q2, [x3, #32]");
    cb.reset();
    try n.dupS(&cb, 4, .x5);
    fails += check(&.{ 0xa4, 0xc, 0x4, 0x4e }, cb.code(), "dup v4.4s, w5");
    cb.reset();
    try n.umovS(&cb, .x0, 7, 3);
    fails += check(&.{ 0xe0, 0x3c, 0x1c, 0xe }, cb.code(), "mov w0, v7.s[3]");
    cb.reset();
    try n.movV(&cb, 1, 2);
    fails += check(&.{ 0x41, 0x1c, 0xa2, 0x4e }, cb.code(), "mov v1.16b, v2.16b");
    try std.testing.expectEqual(@as(u32, 0), fails);
}
